import{_ as i,o as a,c as t,a7 as o}from"./chunks/framework.C4ZIv4ii.js";const s="/falconcms/screenshots/builder-responsive.webp",m=JSON.parse('{"title":"Device Visibility","description":"","frontmatter":{},"headers":[],"relativePath":"builder/visibility.md","filePath":"builder/visibility.md","lastUpdated":1788111091000}'),l={name:"builder/visibility.md"};function n(r,e,d,p,c,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="device-visibility" tabindex="-1">Device Visibility <a class="header-anchor" href="#device-visibility" aria-label="Permalink to &quot;Device Visibility&quot;">​</a></h1><p>Every element in Falcon Builder has visibility controls to show or hide it on specific devices.</p><p><img src="'+s+'" alt="The builder canvas in mobile preview"></p><p><em>Switching the canvas to mobile narrows it to the device width, so you set and check per-device values against the layout the visitor actually gets.</em></p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>In any element&#39;s <strong>General</strong> tab, you&#39;ll find the <strong>Element Visibility</strong> row:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ 🖥 Desktop ] [ 📱 Tablet ] [ 📲 Mobile ]</span></span></code></pre></div><ul><li><strong>Button highlighted (solid)</strong> → visible on that device</li><li><strong>Button dimmed (outline)</strong> → hidden on that device</li></ul><p>Click a button to toggle visibility.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="show-on-desktop-only" tabindex="-1">Show on desktop only <a class="header-anchor" href="#show-on-desktop-only" aria-label="Permalink to &quot;Show on desktop only&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ ✅ Desktop ] [ ❌ Tablet ] [ ❌ Mobile ]</span></span></code></pre></div><p>Use for complex data tables or large images that don&#39;t work on small screens.</p><h3 id="show-on-mobile-only" tabindex="-1">Show on mobile only <a class="header-anchor" href="#show-on-mobile-only" aria-label="Permalink to &quot;Show on mobile only&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ ❌ Desktop ] [ ❌ Tablet ] [ ✅ Mobile ]</span></span></code></pre></div><p>Use for a compact mobile navigation or a &quot;Call Now&quot; button.</p><h3 id="hide-on-mobile" tabindex="-1">Hide on mobile <a class="header-anchor" href="#hide-on-mobile" aria-label="Permalink to &quot;Hide on mobile&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ ✅ Desktop ] [ ✅ Tablet ] [ ❌ Mobile ]</span></span></code></pre></div><p>Use to simplify layouts on small screens by removing decorative elements.</p><h2 id="container-column-visibility" tabindex="-1">Container &amp; Column Visibility <a class="header-anchor" href="#container-column-visibility" aria-label="Permalink to &quot;Container &amp; Column Visibility&quot;">​</a></h2><p>Visibility controls also exist at the <strong>Container</strong> and <strong>Column</strong> level (in their respective settings panels). This lets you:</p><ul><li>Show an entirely different layout section per device</li><li>Have a desktop sidebar column that doesn&#39;t appear on mobile</li><li>Use a mobile-only full-width column in place of a multi-column desktop layout</li></ul><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><p>Visibility is applied via Tailwind CSS classes (<code>hidden</code>, <code>md:block</code>, <code>lg:block</code>) generated from the visibility settings. No JavaScript required — pure CSS responsive hiding.</p>',24)])])}const u=i(l,[["render",n]]);export{m as __pageData,u as default};
